import React, { CSSProperties, useMemo, useState } from 'react';
import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import usePageQuery from '../../core/hooks/usePageQuery';
import { useGetAllCustomerQuery } from '../posApi';
import useCustomerListColumn from './useCustomerListColumn';
import {
  ICustomerDetails,
  ICustomerDetailsData,
} from '../../core/Interface/customer.interface';

const useCustomerList = (
  handleEdit: (data: ICustomerDetailsData) => void,
  handlePayment: (data: ICustomerDetailsData) => void,
  handleDelete: (data: ICustomerDetailsData) => void
) => {
  const { page } = usePageQuery();
  const [popUpUserId, setPopUpUserId] = useState<string>('');
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const {
    data,
    isLoading,
    isFetching,
    error: fetchError,
  } = useGetAllCustomerQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText,
  });

  const customerList = useMemo(() => {
    return data?.data as ICustomerDetails;
  }, [data?.data]);

  const filteredCustomerList = useMemo<ICustomerDetailsData[]>(() => {
    const query = searchText.toLowerCase().trim();

    if (!query) {
      return Array.isArray(customerList?.records) ? customerList.records : [];
    }

    return Array.isArray(customerList?.records)
      ? customerList.records.filter((customer) => {
          const name = (customer.name || '').toLowerCase();
          const mobile = (customer.mobile || '').toLowerCase();
          return name.includes(query) || mobile.includes(query);
        })
      : [];
  }, [customerList, searchText]);

  const columns = useCustomerListColumn({
    handleEdit,
    handleDelete,
    handlePayment,
  });

  const table = useReactTable({
    data: fetchError ? [] : filteredCustomerList,
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    meta: {
      getRowStyles: (row: Row<ICustomerDetailsData>): CSSProperties => ({}),
    },
    pageCount: customerList?.totalRecords ?? 0,
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error: fetchError,
    totalCount: customerList?.totalRecords ?? 0,
    popUpUserId,
    searchText,
    setSearchText,
    setPopUpUserId,
  };
};

export default useCustomerList;
