import React, { useEffect, useState, useMemo } from 'react';
import {
  Box,
  Button,
  Chip,
  InputAdornment,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import usePageQuery from '../../core/hooks/usePageQuery';
import { Table } from '@tanstack/react-table';
import ReactTable from '../../components/Table/ReactTable';
import PosTablePagination from '../../components/Table/PosTablePagination';
import { useDeleteCustomerMutation, useGetUserQuery } from '../posApi';
import { useTranslation } from 'react-i18next';
import useCustomerList from './useCustomerList';
import AnimatedPage from '../../layouts/AnimatedPage';
import AddIcon from '@mui/icons-material/Add';
import PeopleAltOutlinedIcon from '@mui/icons-material/PeopleAltOutlined';
import SearchIcon from '@mui/icons-material/Search';
import DeletePopup from '../../components/ModelPopup/DeletePopup';
import { useNotifier } from '../../core/Notifier';
import useUser from '../../core/hooks/useUser';
import { Privileges } from '../../core/types/commonType';
import NewCustomer from './component/NewCustomer';
import PayPopup from './component/PayPopup';
import { ICustomerDetailsData } from '../../core/Interface/customer.interface';
import { HEADER_GRADIENT } from '../../theme/appColors';

const CustomerList = () => {
  const { setPage } = usePageQuery();
  const { t } = useTranslation(['common', 'customer']);
  const [customerToDelete, setCustomerToDelete] = useState<ICustomerDetailsData | null>(null);
  const { showErrorMessage, showMessage } = useNotifier();
  const { userHasRight } = useUser();
  const [localSearch, setLocalSearch] = useState('');

  const [openPayPopup, setOpenPayPopup] = React.useState(false);
  const [openAddCustomer, setOpenAddCustomer] = useState(false);
  const [openDeleteCustomer, setOpenDeleteCustomer] = useState(false);
  const [customerNameToDelete, setCustomerNameToDelete] = useState('');
  const [customerData, setCustomerData] = React.useState<ICustomerDetailsData | undefined>();

  const handlePaginationChangePage = (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => {
    table.getState().pagination.pageIndex < newPage
      ? table.nextPage()
      : table.previousPage();
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    table.setPageSize(parseInt(event.target.value, 10));
  };

  const handleEdit = (data: ICustomerDetailsData) => {
    setCustomerData(data);
    setOpenAddCustomer(true);
  };

  const handlePayment = (data: ICustomerDetailsData) => {
    setCustomerData(data);
    setOpenPayPopup(true);
  };

  const [deleteCustomer] = useDeleteCustomerMutation();

  const handleDelete = (data: ICustomerDetailsData) => {
    setCustomerToDelete(data);
    setCustomerData(data);
    setCustomerNameToDelete(data.name);
    setOpenDeleteCustomer(true);
  };

  const handleConfirmDelete = async () => {
    if (!customerToDelete) return;
    try {
      const response = await deleteCustomer(customerToDelete.id.toString()).unwrap();
      if (response.status) {
        showMessage(response.message);
        setOpenDeleteCustomer(false);
        setCustomerToDelete(null);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const { table, isLoading, totalCount, setSearchText } = useCustomerList(
    handleEdit,
    handlePayment,
    handleDelete
  );

  useEffect(() => {
    if (
      !isLoading &&
      table.getState().pagination.pageIndex !== 0 &&
      table.getRowModel().rows.length === 0
    ) {
      setPage(0);
    }
  }, [isLoading, setPage, table]);

  const { data: companyData } = useGetUserQuery();

  const isImageEnabled = useMemo(() => {
    if (companyData?.data && typeof companyData.data === 'object' && 'company' in companyData.data) {
      return (companyData.data as { company: { isImageEnabled: boolean } }).company.isImageEnabled ?? false;
    }
    return false;
  }, [companyData]);

  const handleSearch = (text: string) => {
    setSearchText(text);
  };

  return (
    <AnimatedPage>
      <Box data-testid="customer">
        {/* Hero Panel */}
        <Paper
          elevation={0}
          sx={{
            background: HEADER_GRADIENT,
            borderRadius: 2,
            mb: 2,
            overflow: 'hidden',
          }}
        >
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              flexWrap: 'wrap',
              gap: 2,
              justifyContent: 'space-between',
              px: 3,
              py: 2,
            }}
          >
            {/* Title */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  background: 'rgba(255,255,255,0.15)',
                  borderRadius: '10px',
                  display: 'flex',
                  height: 40,
                  justifyContent: 'center',
                  width: 40,
                }}
              >
                <PeopleAltOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
              </Box>
              <Box>
                <Typography sx={{ color: '#fff', fontSize: 18, fontWeight: 800, lineHeight: 1.2 }}>
                  {t('customer:customerManagement')}
                </Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 12, fontWeight: 500 }}>
                  All customers
                </Typography>
              </Box>
              {totalCount > 0 && (
                <Chip
                  label={`${totalCount} records`}
                  size="small"
                  sx={{
                    background: 'rgba(255,255,255,0.18)',
                    border: '1px solid rgba(255,255,255,0.3)',
                    color: '#fff',
                    fontSize: 11,
                    fontWeight: 600,
                  }}
                />
              )}
            </Box>

            {/* Search + Add */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: '10px' }}>
              <TextField
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 18 }} />
                    </InputAdornment>
                  ),
                }}
                onChange={(e) => setLocalSearch(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') handleSearch(localSearch); }}
                placeholder={t('customer:searchPlaceholder')}
                size="small"
                sx={{
                  minWidth: 260,
                  '& .MuiOutlinedInput-root': {
                    background: 'rgba(255,255,255,0.12)',
                    borderRadius: '8px',
                    color: '#fff',
                    height: 40,
                    '& fieldset': { borderColor: 'rgba(255,255,255,0.25)' },
                    '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.5)' },
                    '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.8)' },
                    '& input::placeholder': { color: 'rgba(255,255,255,0.55)', opacity: 1 },
                  },
                }}
                value={localSearch}
                variant="outlined"
              />
              <Button
                onClick={() => handleSearch(localSearch)}
                sx={{
                  background: 'rgba(255,255,255,0.15)',
                  border: '1px solid rgba(255,255,255,0.3)',
                  borderRadius: '8px',
                  color: '#fff',
                  flexShrink: 0,
                  fontWeight: 600,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'rgba(255,255,255,0.25)' },
                }}
                variant="contained"
              >
                {t('common:search')}
              </Button>

              {userHasRight(Privileges.CustomerManageAdd) && (
                <Button
                  onClick={() => { setCustomerData(undefined); setOpenAddCustomer(true); }}
                  startIcon={<AddIcon />}
                  sx={{
                    background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                    borderRadius: '8px',
                    boxShadow: '0 4px 14px rgba(37,99,235,0.35)',
                    color: '#fff',
                    flexShrink: 0,
                    fontWeight: 700,
                    height: 40,
                    px: 2.5,
                    '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                  }}
                  variant="contained"
                >
                  Customer
                </Button>
              )}
            </Box>
          </Box>
        </Paper>

        {/* Table */}
        <Paper
          elevation={0}
          sx={{
            border: '1px solid #E2E8F0',
            borderRadius: 2,
            overflow: 'hidden',
          }}
        >
          <Box sx={{ maxWidth: '100%', minHeight: 480, overflow: 'auto' }}>
            <ReactTable isLoading={isLoading} {...(table as Table<object>)} />
          </Box>

          {table.getTotalSize() !== 0 && (
            <PosTablePagination
              count={totalCount}
              data-testid="pos-pagination"
              onPageChange={handlePaginationChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
              page={table.getState().pagination.pageIndex}
              rowsPerPage={table.getState().pagination.pageSize}
              rowsPerPageOptions={[5, 10, 20]}
            />
          )}
        </Paper>

        {openAddCustomer && (
          <NewCustomer
            data={customerData}
            handleCloseDialog={() => setOpenAddCustomer(false)}
            isImageEnabled={isImageEnabled}
            openModel={openAddCustomer}
            title={`${customerData ? t('customer:edit') : t('customer:addCustomer')}`}
          />
        )}

        {openPayPopup && (
          <PayPopup
            data={customerData}
            handleCloseDialog={() => setOpenPayPopup(false)}
            openModel={openPayPopup}
            title={`${customerData ? t('customer:amount') : t('customer:addCustomer')}`}
          />
        )}

        {openDeleteCustomer && (
          <DeletePopup
            content={`${t('customer:confirmMessage')} "${customerNameToDelete}"?`}
            handleCloseDelete={() => setOpenDeleteCustomer(false)}
            onConfirm={handleConfirmDelete}
            open={openDeleteCustomer}
            title={t('customer:deleteCustomer')}
          />
        )}
      </Box>
    </AnimatedPage>
  );
};

export default CustomerList;
